"use client";

import { useEffect, useId, useRef, useState } from "react";
import Link from "next/link";
import { MoneyText } from "@salesmora/ui";
import { initialEstimateConversionReview } from "../estimate-convert-dialog/estimate-convert-dialog.preview";
import { estimateConvertDialogData as dialog } from "../estimate-convert-dialog/estimate-convert-dialog.data";
import { estimateConvertCardData as c } from "./estimate-convert-card.data";
import { estimateConvertCardRequest, reviewEstimateConvertCard } from "./estimate-convert-card.preview";
import type { EstimateConvertCardDecision, EstimateConvertCardProps } from "./estimate-convert-card.types";

export type { EstimateConvertCardProps } from "./estimate-convert-card.types";

export function EstimateConvertCard(props: EstimateConvertCardProps) {
  const id = useId();
  if (!props.capabilities.read || !props.parentAccess || props.proposal.state === "forbidden" || props.context?.customer.state === "unavailable") {
    return <section aria-labelledby={id} className="rounded-xl border border-assistant-border bg-assistant-surface p-5 text-assistant-foreground print:hidden">
      <h3 id={id} className="m-0 text-lg font-semibold">{c.title}</h3>
      <p role="status" className="mb-0 mt-3 text-sm leading-6">{c.unavailable}</p>
    </section>;
  }
  const session = JSON.stringify({
    proposal: props.proposal, context: props.context, capabilities: props.capabilities, parentAccess: props.parentAccess,
    canCreateJob: props.canCreateJob, handler: !!props.onDecide,
  });
  return <ConversionReview key={session} {...props} />;
}

function ConversionReview(props: EstimateConvertCardProps) {
  const { proposal, disabled = false, onDecide } = props;
  const id = useId(), locked = useRef(false), mounted = useRef(false);
  const [clock, setClock] = useState(Date.now);
  const [working, setWorking] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");
  const review = reviewEstimateConvertCard(props, clock);
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);
  useEffect(() => {
    if (review.expires === null) return;
    const expires = review.expires;
    let timer: ReturnType<typeof setTimeout>;
    const check = () => {
      const now = Date.now();
      if (expires <= now) setClock(now);
      else timer = setTimeout(check, Math.min(2147483647, expires - now));
    };
    check();
    return () => clearTimeout(timer);
  }, [review.expires]);
  const state = proposal.state === "pending" && review.expired ? "expired" : proposal.state;
  const active = state === "pending" && !submitted, busy = disabled || working;
  async function decide(decision: EstimateConvertCardDecision["decision"]) {
    if (locked.current || busy || !active || !onDecide) return;
    const current = reviewEstimateConvertCard(props, Date.now());
    if (current.expired) { setClock(Date.now()); return; }
    if (!(decision === "review" ? current.canReview : current.canCancel)) {
      setError(current.issues[0] ?? c.failure);
      return;
    }
    locked.current = true; setWorking(true); setError("");
    try {
      const result = await onDecide({ ...estimateConvertCardRequest(proposal), decision });
      if (!mounted.current) return;
      if (!result.ok) setError(result.message.trim() || c.failure);
      else setSubmitted(true);
    } catch {
      if (mounted.current) setError(c.failure);
    } finally {
      if (mounted.current) { locked.current = false; setWorking(false); }
    }
  }
  const record = proposal.estimate, job = initialEstimateConversionReview(record, proposal.customer).job;
  const button = "min-h-11 max-w-full cursor-pointer rounded-xl px-4 py-2 text-sm font-semibold whitespace-normal wrap-anywhere focus-visible:focus-ring disabled:cursor-not-allowed disabled:opacity-50";
  return <section aria-labelledby={id} aria-busy={working} className="grid min-w-0 gap-4 rounded-xl border border-assistant-border bg-assistant-surface p-5 text-assistant-foreground print:hidden">
    <h3 id={id} className="m-0 text-lg font-semibold">{c.title}</h3>
    <p className="m-0 text-sm leading-6 text-assistant-muted">{c.description}</p>
    <section aria-labelledby={`${id}-source`} className="grid min-w-0 gap-4">
      <h4 id={`${id}-source`} className="m-0 text-base font-semibold">{c.source}</h4>
      <dl className="m-0 grid min-w-0 gap-4 text-sm">
        {([
          [c.number, <>{record.number || c.missing} · {c.revision(record.revision)} · {record.name || c.missing}</>],
          [c.amount, record.totalCents === null || !Number.isSafeInteger(record.totalCents) || record.totalCents < 0
            ? c.missing : <MoneyText cents={record.totalCents} />],
          [record.parentType === "job" ? c.parentJob : c.lead, record.parentNumber || c.missing],
          [c.customer, proposal.customer.state === "ready" ? proposal.customer.name || c.missing : c.missing],
        ] as const).map(([label, content]) => <div key={label} className="min-w-0">
          <dt className="font-semibold text-assistant-muted">{label}</dt>
          <dd className="m-0 mt-1 leading-6 wrap-anywhere">{content}</dd>
        </div>)}
      </dl>
    </section>
    <section aria-labelledby={`${id}-work`} className="grid min-w-0 gap-4 rounded-xl border border-assistant-border bg-assistant-message p-4">
      <h4 id={`${id}-work`} className="m-0 text-base font-semibold">{c.work}</h4>
      <dl className="m-0 grid min-w-0 gap-4 text-sm">
        {(Object.keys(c.fields) as (keyof typeof c.fields)[]).map((field) => <div key={field} className="min-w-0">
          <dt className="font-semibold text-assistant-muted">{c.fields[field]}</dt>
          <dd className="m-0 mt-1 whitespace-pre-wrap leading-6 wrap-anywhere">{job[field] || c.missing}</dd>
        </div>)}
      </dl>
      <p className="m-0 text-sm leading-6 text-assistant-muted">{c.defaults}</p>
    </section>
    {record.scope.length > 4000 && <p className="m-0 text-sm leading-6">{c.longScope}</p>}
    {review.issues.length > 0 && <ul aria-label={c.issuesLabel} className="m-0 grid min-w-0 gap-2 pl-5 text-sm leading-6">
      {review.issues.map((issue) => <li key={issue} className="wrap-anywhere">{issue}</li>)}
    </ul>}
    {proposal.customer.state === "missing" && <p className="m-0 text-sm leading-6 text-assistant-muted">{c.customerHint}</p>}
    {review.existingJob && <Link href={review.existingJob.href} aria-disabled={busy} tabIndex={busy ? -1 : undefined}
      onClick={(event) => { if (busy) event.preventDefault(); }}
      className={`${button} justify-self-start border border-assistant-border text-assistant-accent`}>{dialog.openJob(review.existingJob.number)}</Link>}
    {review.expires !== null && <p className="m-0 text-xs leading-5 text-assistant-muted">
      {c.expires}: <time dateTime={proposal.expiresAt}>{new Date(review.expires).toISOString().replace("T", " ").replace("Z", " UTC")}</time>
    </p>}
    <p className="m-0 text-sm leading-6 text-assistant-muted">{c.amountHint}</p>
    <p className="m-0 text-sm leading-6 text-assistant-muted">{c.effects}</p>
    <p role="status" className="m-0 text-sm font-semibold leading-6">{working ? c.working : state !== "pending"
      ? c.states[state] : submitted ? c.requested : c.states.pending}</p>
    {error && <p role="alert" className="m-0 text-sm leading-6">{error}</p>}
    {!onDecide && state === "pending" && <p className="m-0 text-sm leading-6">{c.noHandler}</p>}
    {active && onDecide && <div className="flex flex-wrap gap-3">
      <button type="button" disabled={busy || !review.canReview} className={`${button} bg-assistant-accent text-assistant-surface`}
        onClick={() => { void decide("review"); }}>{c.review}</button>
      <button type="button" disabled={busy || !review.canCancel} className={`${button} border border-assistant-border text-assistant-accent`}
        onClick={() => { void decide("cancel"); }}>{c.cancel}</button>
    </div>}
  </section>;
}
